var n=`1003-green-curry`;var t=`world-1003`;var s=`TH`;var a=`southeast-asia`;var r=4;var h=32;var o={en:`Green Curry`,ua:`Зелене карі`};var g={en:`Green Curry is a dish from Thailand prepared with thai green curry paste, coconut cream, chicken thigh, coconut milk. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Зелене карі, страва кухні країни Таїланд, яку готують із таких продуктів: зелена тайська паста карі, кокосові вершки, куряче стегно, кокосове молоко. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 4 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 4 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:4,i:[[`thai-green-curry-paste`,80,`g`],[`coconut-cream`,170,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 22 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 22 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:22,i:[[`chicken-thigh`,650,`g`],[`coconut-milk`,450,`ml`],[`thai-eggplant`,260,`g`],[`bamboo-shoots`,180,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`fish-sauce`,35,`ml`],[`palm-sugar`,22,`g`],[`makrut-lime-leaves`,4,`leaf`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`thai-basil`,20,`g`],[`serrano-pepper`,1,`pcs`]]}];var d={slug:n,id:t,country:`TH`,region:a,servings:4,minutes:32,title:o,text:g,steps:u};export{s as country,d as default,t as id,h as minutes,a as region,r as servings,n as slug,u as steps,g as text,o as title};